BEGIN = '/* __DESKTOP_SECURITY_I18N_2026_11_20__ BEGIN — generated by OSHI-Desktop/i18n-src/security/security_strings.py */'
END = '/* __DESKTOP_SECURITY_I18N_2026_11_20__ END */'
def esc(v): return v.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n')
if __name__ == '__main__':
    root = sys.argv[1]
    for lang, vals in S.items():
        assert len(vals) == len(KEYS), lang
        p = os.path.join(root, f'{lang}.lproj', 'Localizable.strings')
        s = open(p, encoding='utf-8').read()
        s = re.sub(re.escape(BEGIN) + r'.*?' + re.escape(END) + r'\n?', '', s, flags=re.S).rstrip('\n') + '\n'
        lines = [BEGIN] + [f'"{k}" = "{esc(v)}";' for k, v in zip(KEYS, vals)] + [END]
        open(p, 'w', encoding='utf-8').write(s + '\n'.join(lines) + '\n')
    print(len(S), 'locales')
